uint32_t crc = crc ^ 0xffffffffu;
for (size_t i = 0; i < size; i++) {
    uint8_t b = static_cast<const uint8_t*>(buffer)[i];
    crc = crc ^ b;
    for (int j = 0; j < 8; j++) {
        if (crc & 1) {
            crc = (crc >> 1) ^ 0xedb88320u;
        } else {
            crc >>= 1;
        }
    }
}
return crc ^ 0xffffffffu;

